_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

_DIGIT_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(number):
    """Roman numeral for an int from 1 to 3999."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise ValueError("number must be an int from 1 to 3999")
    if not 1 <= number <= 3999:
        raise ValueError("number must be in the range 1 to 3999")
    parts = []
    remaining = number
    for value, symbol in _VALUES:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return "".join(parts)


def from_roman(text):
    """The int for a standard Roman numeral."""
    if not isinstance(text, str) or not text:
        raise ValueError("not a Roman numeral")
    total = 0
    previous = 0
    for char in reversed(text):
        if char not in _DIGIT_VALUES:
            raise ValueError("invalid character in Roman numeral: %r" % char)
        value = _DIGIT_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    # Accept only the exact canonical text that to_roman produces for this value.
    if not 1 <= total <= 3999 or to_roman(total) != text:
        raise ValueError("not a standard Roman numeral: %r" % text)
    return total
